<script setup>
import {ref} from 'vue'; import {Head,useForm,router} from '@inertiajs/vue3'; import Layout from '@/Layouts/main.vue';
const p=defineProps({batches:Array,cards:Array,coupons:Array}); const f=useForm({name:'',quantity:100,expires_at:'',coupon_quantities:Object.fromEntries(p.coupons.map(c=>[c.id,1]))}); const generating=ref(false);
async function create(){generating.value=true;try{const response=await window.axios.post(route('card-batches.store'),f.data(),{responseType:'blob'});const url=URL.createObjectURL(response.data);const a=document.createElement('a');a.href=url;a.download=`${f.name||'lote'}-codigos.csv`;a.click();URL.revokeObjectURL(url);router.reload()}finally{generating.value=false}}
const toggle=c=>router.patch(route('cards.status',c.id));
</script>
<template><Layout><Head title="Tarjetas y lotes"/><main class="page"><header><div><small>ACTIVACIONES</small><h1>Tarjetas y lotes</h1><p>Genera códigos para impresión y controla su activación.</p></div><div><a :href="route('exports.members')">Exportar socios</a><a :href="route('exports.summary')">Exportar resumen</a></div></header><section class="grid"><form @submit.prevent="create"><h2>Nuevo lote</h2><label>Referencia<input v-model="f.name" required></label><label>Cantidad de tarjetas<input v-model="f.quantity" type="number" min="1" max="5000" required></label><label>Vencimiento <i>Opcional</i><input v-model="f.expires_at" type="date"></label><fieldset><legend>Cupones por cuponera</legend><label v-for="c in coupons" :key="c.id">{{c.name}}<input v-model="f.coupon_quantities[c.id]" type="number" min="0" max="50"></label></fieldset><small class="error">{{f.errors.name||f.errors.quantity||f.errors.coupon_quantities}}</small><button :disabled="f.processing">Generar y descargar códigos</button></form><section><h2>Lotes</h2><article v-for="b in batches" :key="b.id"><b>{{b.name}}</b><span>{{b.activated_count}} activadas · {{b.available_count}} disponibles · {{b.cards_count}} total</span></article></section></section><section class="cards"><h2>Últimas tarjetas</h2><table><thead><tr><th>Tarjeta</th><th>Lote</th><th>Socio</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="c in cards" :key="c.id"><td>•••• {{c.activation_code_last4}}</td><td>{{c.batch?.name}}</td><td>{{c.member?.name||'Sin registrar'}}</td><td>{{c.status}}</td><td><button v-if="['available','blocked'].includes(c.status)" @click="toggle(c)">{{c.status==='blocked'?'Desbloquear':'Bloquear'}}</button></td></tr></tbody></table></section></main></Layout></template>
<style scoped>.page{max-width:1300px;margin:auto;color:#332820}.page>header{display:flex;justify-content:space-between;align-items:end}.page>header small{color:#993b2a;letter-spacing:.2em}.page>header a{display:inline-block;margin-left:8px;background:#576443;color:white;padding:10px;border-radius:8px}h1,h2{font-family:Georgia}.grid{display:grid;grid-template-columns:420px 1fr;gap:20px;margin-top:25px}.grid>form,.grid>section,.cards{background:white;padding:22px;border-radius:15px}label{display:block;margin:10px 0;font-size:12px;font-weight:700}input{display:block;width:100%;padding:9px;border:1px solid #d9cdbd;border-radius:7px}fieldset label{display:grid;grid-template-columns:1fr 80px;align-items:center}.grid article{display:flex;justify-content:space-between;padding:14px;border-bottom:1px solid #eee}.grid article span{color:#776}.grid form>button{width:100%;background:#993b2a;color:white;border:0;padding:12px;border-radius:8px}.error{color:#993b2a}.cards{margin-top:20px;overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-top:1px solid #eee}td button{border:1px solid #993b2a;color:#993b2a;background:white;border-radius:7px;padding:6px}@media(max-width:850px){.grid{grid-template-columns:1fr}.page>header{align-items:start;flex-direction:column;gap:12px}}</style>
